import{_ as i,c as a,o as e,af as t}from"./chunks/framework.CpuDhtGM.js";const _=JSON.parse('{"title":"经营失败","description":"","frontmatter":{},"headers":[],"relativePath":"value-investing/governance/business-failure.md","filePath":"value-investing/governance/business-failure.md","lastUpdated":1765960072000}'),o={name:"value-investing/governance/business-failure.md"};function r(s,l,u,n,d,h){return e(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="经营失败" tabindex="-1">经营失败 <a class="header-anchor" href="#经营失败" aria-label="Permalink to &quot;经营失败&quot;">​</a></h1><h2 id="企业经营失败的原因分析" tabindex="-1">企业经营失败的原因分析 <a class="header-anchor" href="#企业经营失败的原因分析" aria-label="Permalink to &quot;企业经营失败的原因分析&quot;">​</a></h2><h3 id="一、企业未能适应外部环境的重大变化" tabindex="-1">一、企业未能适应外部环境的重大变化 <a class="header-anchor" href="#一、企业未能适应外部环境的重大变化" aria-label="Permalink to &quot;一、企业未能适应外部环境的重大变化&quot;">​</a></h3><ul><li><ol><li>技术变化或颠覆式创新的出现，导致企业主营产品所在品类整体不再被人们所需要</li></ol><ul><li>企业忽视了主营产品价值主张背后用户的底层需求。当技术变化或颠覆式创新出现，用户的底层需求被创新产品更好地满足时，企业主营产品所在的品类整体不再被人们需要。</li><li>这时，无论企业将产品做得多么精益求精，服务做得多么尽善尽美，都难以再挽回用户。</li><li>打败汽车的可能不是另外一种“车”​，而可能是眼镜什么的。这就像现在越来越多被谈到的“跨界竞争”和“降维打击”​。</li><li>每家企业似乎都有自己的宿命，在遭遇创新者的窘境时，企业很难改变自己的基因，从而落入失败。为了让投资变得简单，我们尽量避开转型期的企业，毕竟作为投资者我们掉头比企业简单得多。</li></ul></li><li><ol start="2"><li>重大事故和危机</li></ol><ul><li>一些重要事故导致企业破产，只是最后一根稻草，企业往往内部已经出现了问题，这是“风化”​。​“风化”久了，一次特殊事件就可能导致“山崩”​。</li></ul></li><li><ol start="3"><li>企业的命运过度依赖他人</li></ol><ul><li>当一家企业的命运掌握在他人手中，就有失败的风险。苹果供应链上的一些供应商企业就因为苹果选择新的供应商而破产。</li><li>在选择投资对象时，我们应仔细分析那些过度依赖重要客户或重要供应商的企业是否存在风险。命运系于他人的企业往往过于脆弱，哪怕一时获得很多订单，也不是好的投资对象。</li></ul></li></ul><h3 id="二、企业的重大战略、经营决策、内部治理出现问题" tabindex="-1">二、企业的重大战略、经营决策、内部治理出现问题 <a class="header-anchor" href="#二、企业的重大战略、经营决策、内部治理出现问题" aria-label="Permalink to &quot;二、企业的重大战略、经营决策、内部治理出现问题&quot;">​</a></h3><ul><li><ol><li>经营决策失误</li></ol></li><li><ol start="2"><li>盲目多元化</li></ol><ul><li>多元化本身未必一定会导致企业失败，有时反而使企业更加成功。</li><li>失败的多元化 <ul><li><ol><li>一是企业成功后盲目自大，进入自己能力圈之外的领域；</li></ol></li><li><ol start="2"><li>二是企业面临短期困境时病急乱投医，盲目进入新业务，以至于主业失败。</li></ol></li></ul></li></ul></li><li><ol start="3"><li>经营激进导致资金链断裂</li></ol><ul><li>企业家往往具备一些冒险精神，也具有野心。当这种野心不受约束，超过了现实条件的允许时，就可能导致企业的失败。</li></ul></li><li><ol start="4"><li>过度追求短期利润，管理失控、产品质量下降</li></ol></li><li><ol start="5"><li>竞争失败</li></ol><ul><li>快的、优步被滴滴打败，易趣中国被淘宝打败，米聊被微信打败。一种新的商业模式兴起时，往往有多个甚至成百上千个竞争对手，最终活下来的可能只有两三个。</li></ul></li><li><ol start="6"><li>管理层矛盾</li></ol><ul><li>将导致企业无法聚精会神发展业务，导致企业失败。</li></ul></li><li><ol start="7"><li>大股东挪用公司资金</li></ol></li></ul><h3 id="三、企业的价值观偏离了正道" tabindex="-1">三、企业的价值观偏离了正道 <a class="header-anchor" href="#三、企业的价值观偏离了正道" aria-label="Permalink to &quot;三、企业的价值观偏离了正道&quot;">​</a></h3><ul><li><ol><li>财务造假</li></ol><ul><li>企业财务造假的原因要么是谋求业绩和股价增长，要么是从资本市场获得融资，根本的原因是企业的核心价值观偏离了正道。</li></ul></li><li><ol start="2"><li>业务造假</li></ol></li><li><ol start="3"><li>违背政府政策或社会公序良俗，触碰到监管底线</li></ol></li></ul><p>一家企业的失败往往并不是一个因素，而是多个因素共同作用的结果。在投资中，掌握了企业失败的一般性原因，我们可以提前警惕到企业的失败。</p><p>——《投资至简：从原点出发构建价值投资体系》第二章 第六节 企业经营失败的原因分析</p>',10)])])}const f=i(o,[["render",r]]);export{_ as __pageData,f as default};
